      "ledger_id": "A2",
      "description": "Escalated to maintenance as ESC-101 to reconcile contractor, tenant identity/phone and visit date."
    },
    {
      "ledger_id": "A3",
      "description": "Holding email sent to tenant Clara on existing thread (event 015) confirming approval and that booking details are being checked."
    }
